18	// The handshake needs uint64 flags[ws] followed by uint64 epoch. It lives in the LAST slots of the
19	// allocation's signal pad, because torch's own SymmetricMemory::barrier() -- which window setup
20	// calls -- uses channels counted from the front, and the two must not overlap.
21	int64_t flag_slots(int world_size)
22	{
23	    return world_size + 1;
24	}
25	
26	int64_t flag_offset_slots(int world_size)
27	{
28	    const int64_t pad_slots = static_cast<int64_t>(symm::get_signal_pad_size()) / 8;
29	    TORCH_CHECK(pad_slots >= flag_slots(world_size) + 8,
30	                "the symmetric-memory signal pad holds ",
31	                pad_slots,
32	                " uint64 slots, too few for a ",
33	                world_size,
34	                "-rank handshake plus torch's own channels. Raise it with "
35	                "torch.distributed._symmetric_memory.set_signal_pad_size() before any allocation.");
36	    return pad_slots - flag_slots(world_size);
37	}
